package bridge

import (
	"testing"
)

// TestAudioFileExt tests audio file extension detection based on content type and MIME type.
func TestAudioFileExt(t *testing.T) {
	tests := []struct {
		name       string
		contentType string
		mimeType    string
		expected    string
	}{
		{
			name:       "voice message returns ogg",
			contentType: "voice",
			mimeType:    "",
			expected:    "ogg",
		},
		{
			name:       "mpeg audio returns mp3",
			contentType: "audio",
			mimeType:    "audio/mpeg",
			expected:    "mp3",
		},
		{
			name:       "mp3 audio returns mp3",
			contentType: "audio",
			mimeType:    "audio/mp3",
			expected:    "mp3",
		},
		{
			name:       "m4a audio returns m4a",
			contentType: "audio",
			mimeType:    "audio/mp4",
			expected:    "m4a",
		},
		{
			name:       "audio/x-m4a returns m4a",
			contentType: "audio",
			mimeType:    "audio/x-m4a",
			expected:    "m4a",
		},
		{
			name:       "flac audio returns flac",
			contentType: "audio",
			mimeType:    "audio/flac",
			expected:    "flac",
		},
		{
			name:       "ogg audio returns ogg",
			contentType: "audio",
			mimeType:    "audio/ogg",
			expected:    "ogg",
		},
		{
			name:       "wav audio returns wav",
			contentType: "audio",
			mimeType:    "audio/wav",
			expected:    "wav",
		},
		{
			name:       "x-wav audio returns wav",
			contentType: "audio",
			mimeType:    "audio/x-wav",
			expected:    "wav",
		},
		{
			name:       "unknown audio defaults to mp3",
			contentType: "audio",
			mimeType:    "audio/unknown",
			expected:    "mp3",
		},
		{
			name:       "empty mimeType defaults to mp3",
			contentType: "audio",
			mimeType:    "",
			expected:    "mp3",
		},
	}

	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			got := audioFileExt(tc.contentType, tc.mimeType)
			if got != tc.expected {
				t.Errorf("audioFileExt(%q, %q) = %q, want %q", tc.contentType, tc.mimeType, got, tc.expected)
			}
		})
	}
}
